// surfCompiledGallery is c drawn by its templates compiled into Go.
func surfCompiledGallery(c *Gallery) surflive.Component {
	return surf.Compiled(c, "gallery.surf", func(e *surf.Errs) []*surfui.Node { return surfRenderGallery(e, nil, c, nil) })
}

// surfList1 is a []*Control as a list.
type surfList1 []*Control

func (l surfList1) Len() int               { return len(l) }
func (l surfList1) At(i int) cellite.Value { return surfControlValue(l[i]) }

// surfList1Of is a list's value as a []*Control.
func surfList1Of(v cellite.Value) []*Control {
	l := v.List()
	if l == nil {
		return nil
	}
	out := make([]*Control, l.Len())
	for i := range out {
		out[i] = surfControlOf(l.At(i))
	}
	return out
}

